"""Problem module generated by generate-kernel.py optimize — do not edit.
Optimization target: benchmark case 0 = (1024, 1024, 1024, 'float16').
Model is the stateless PyTorch reference used as the baseline; the optimized
kernel must keep computing the result itself, in Triton, with the exact wrapper
signature required by the problem description below. get_inputs() returns the
kernel_function arguments in calling order, so the benchmark and profiling
harnesses invoke the kernel exactly like the fixed benchmark does. The
problem's spec.py is copied verbatim below, so every helper and constant it
defines is available to make_inputs() and reference().

Implement a fused matrix multiplication with bias addition as a Triton kernel.

Wrapper signature (must be defined at the top level of kernel.py):
    def kernel_function(A, B, bias):

Inputs:
- A: 2D tensor of shape (M, K), dtype float16 or bfloat16, contiguous, on CUDA
- B: 2D tensor of shape (K, N), dtype float16 or bfloat16, contiguous, on CUDA
- bias: 1D tensor of shape (N,), same dtype as A, on CUDA

Output:
- 2D tensor of shape (M, N), same dtype as A, containing (A @ B) + bias,
  with the bias broadcast additively over every row

Requirements:
- Compute the matrix multiplication inside one or more @triton.jit kernels and
  accumulate in float32 (use tl.dot with an fp32 accumulator)
- The wrapper kernel_function must allocate the output tensor, launch the
  Triton kernel(s), and return the output tensor
- Handle arbitrary M, K, N, including sizes that are not multiples of the
  chosen block sizes (mask boundary loads and stores)
- Support both float16 and bfloat16 inputs
- Do NOT use torch.matmul / torch.mm / torch.bmm / torch.einsum, cuBLAS,
  cuSolver, or any PyTorch compute op to produce the result; only Triton
  kernels may perform the computation (allocating tensors with torch.empty
  or torch.zeros is allowed)
- Wrap the matmul @triton.jit kernel in @triton.autotune with a small
  (about 4-8 entries) config space of triton.Config objects that sweeps
  BLOCK_M, BLOCK_N, BLOCK_K and num_warps/num_stages for good performance
  on the target GPU: NVIDIA RTX 5000 Ada Generation Laptop GPU (16GB, compute capability 8.9, Ada Lovelace, sm_89)
- Build the grid from the selected config (for example
  grid = lambda meta: ... using meta["BLOCK_M"] and meta["BLOCK_N"]) so the
  autotuner's choice actually takes effect, and key the autotuner on the
  shape inputs (M, N, K)
- Keep the config space small enough to compile and tune quickly on this
  GPU and within its shared-memory limit; a config that cannot launch is
  silently scored as infinity by the autotuner
"""

from __future__ import annotations

import torch
import torch.nn as nn


"""Case data, input construction, and reference ops for matmul + bias.

The single source of truth for what a benchmark/test case *is*: bench.py
and test_fixed.py drive this module through problems/_harness.py, and
generate-kernel.py's optimizer adapter embeds make_inputs()/reference()
verbatim (via inspect.getsource) rather than re-deriving them — so there is
exactly one copy of this logic, and profile-kernel.py, bench.py, and the
optimizer's Model can never silently disagree about what case 0 means.

No torch import at module level: generate-kernel.py's and
profile-kernel.py's parent processes load this module just to read
BENCH_CASES (shapes, dtypes, a seed base) before forking worker processes,
and must not initialize CUDA or even import torch to do it. Dtypes are
therefore plain attribute names ("float16"), and make_inputs()/reference()
import torch lazily, inside the function body, so only the processes that
actually build tensors pay for it.
"""

# Benchmark cases: performance-oriented shapes (large, realistic), used by
# bench.py, profile-kernel.py, and the optimizer's problem module.
BENCH_CASES = [
    (1024, 1024, 1024, "float16"),
    (2048, 1024, 2048, "float16"),
    (2048, 2048, 2048, "bfloat16"),
    (4096, 4096, 4096, "float16"),
]

# Fixed-test cases: correctness-oriented shapes (aligned, non-tile-aligned,
# tiny), used by test_fixed.py only.
TEST_CASES = [
    (128, 128, 128, "float16"),
    (256, 512, 128, "bfloat16"),
    (64, 32, 16, "float16"),
    (100, 77, 51, "bfloat16"),
    (333, 65, 129, "float16"),
    (1024, 256, 512, "bfloat16"),
]

BENCH_SEED_BASE = 2000
TEST_SEED_BASE = 1000
FP16_TOL = 1e-2


def make_inputs(case, seed):
    """(A, B, bias) for one case, matching the kernel's expected signature."""
    import torch

    M, K, N, dtype_name = case
    dt = getattr(torch, dtype_name)
    torch.manual_seed(seed)
    A = torch.randn(M, K, device="cuda", dtype=dt) * 0.25
    B = torch.randn(K, N, device="cuda", dtype=dt) * 0.25
    bias = torch.randn(N, device="cuda", dtype=dt) * 0.5
    return A, B, bias


def output_shape(case):
    M, K, N, _dtype_name = case
    return (M, N)


def describe(case):
    M, K, N, dtype_name = case
    return f"M={M} K={K} N={N} {dtype_name}"


def case_fields(case):
    M, K, N, _dtype_name = case
    return {"M": M, "K": K, "N": N}


def flops(case):
    M, K, N, _dtype_name = case
    return 2.0 * M * K * N


def reference(A, B, bias):
    """Native-dtype PyTorch baseline: the speed comparison in bench.py and
    profile-kernel.py, and the Model the optimizer benchmarks/profiles
    against."""
    import torch

    return torch.addmm(bias, A, B)


def reference_precise(A, B, bias):
    """Upcast reference for test_fixed.py's correctness check."""
    import torch

    return (torch.matmul(A.float(), B.float()) + bias.float()).to(A.dtype)


class Model(nn.Module):
    """PyTorch baseline (reference only); see reference() above."""

    def forward(self, *args):
        return reference(*args)


CASE = (1024, 1024, 1024, 'float16')
SEED = 2000


def get_inputs():
    return list(make_inputs(CASE, SEED))


def get_init_inputs():
    return []
